import { Workbook } from '@syncfusion/ej2-excel-export';
import * as events from '../../common/base/constant';
import { isNullOrUndefined, initializeTelemetryFeature } from '@syncfusion/ej2-base';
import { PivotExportUtil } from '../../base/export-util';
import { ExcelExportHelper } from './excel-export-helper';
import { PivotUtil } from '../../base/util';
/**
 * @hidden
 * `ExcelExport` module is used to handle the Excel export action.
 */
export class ExcelExport {
    /**
     * Constructor for the PivotGrid Excel Export module.
     *
     * @param {PivotView} parent - Instance of pivot table.
     * @hidden
     */
    constructor(parent) {
        this.actualrCnt = 0;
        /** @hidden */
        this.images = [];
        this.workSheet = [];
        this.isHeaderIncluded = false;
        this.book = {};
        initializeTelemetryFeature('ExcelExport', 'PivotTable');
        this.parent = parent;
        this.excelExportHelper = new ExcelExportHelper(this.parent);
        this.rows = [];
    }
    /**
     * For internal use only - Get the module name.
     *
     * @returns {string} - string.
     * @private
     */
    getModuleName() {
        return 'excelExport';
    }
    addHeaderAndFooter(excelExportProperties, stringValue, type, rowCount) {
        if (!this.rows) {
            this.rows = [];
        }
        let cells = [];
        if (!isNullOrUndefined(excelExportProperties.rows)) {
            this.actualrCnt = (type === 'footer') ? this.actualrCnt + rowCount - (excelExportProperties.rows[0].cells.length) : this.actualrCnt;
            const row = excelExportProperties.rows;
            for (let i = 0; i < row.length; i++) {
                let spanCount = 0;
                cells = [];
                const currentRow = row[i];
                for (let j = 0; j < currentRow.cells.length; j++) {
                    const cell = {
                        index: spanCount + 1, value: currentRow.cells[j].value,
                        colSpan: currentRow.cells[j].colSpan, rowSpan: currentRow.cells[j].rowSpan,
                        style: !isNullOrUndefined(this.theme) && !isNullOrUndefined(this.theme.caption) ?
                            this.excelExportHelper.getCaptionThemeStyle(this.theme, currentRow.cells[j].style)
                            : currentRow.cells[j].style
                    };
                    if (currentRow.cells[j].hyperlink) {
                        cell.hyperlink = { target: currentRow.cells[j].hyperlink.target };
                        cell.value = currentRow.cells[j].value ? currentRow.cells[j].value :
                            currentRow.cells[j].hyperlink.displayText;
                    }
                    cells.push(cell);
                    spanCount = spanCount + cells[j].colSpan;
                }
                this.actualrCnt++;
                this.rows.push({ index: this.actualrCnt, cells: cells });
            }
            this.actualrCnt = (type === 'header') ? rowCount : this.actualrCnt;
        }
        else {
            if (stringValue !== '') {
                if (type === 'footer') {
                    this.actualrCnt++;
                }
                cells.push({
                    index: 1, value: stringValue
                });
                this.rows.push({ index: this.actualrCnt + 1, cells: cells });
                this.actualrCnt = (type === 'header') ? this.actualrCnt + 2 : this.actualrCnt;
            }
        }
    }
    /**
     *
     * Method to perform excel export.
     *
     * @hidden
     */
    exportToExcel(type, exportProperties, isBlob, workBook, isMultipleExport, currentPivotInstance) {
        return new Promise((resolve, reject) => {
            try {
                this.actualrCnt = 0;
                let expType = 'AppendToSheet';
                let blankRows = 5;
                if (!isNullOrUndefined(exportProperties) && !isNullOrUndefined(exportProperties.multipleExport)) {
                    expType = (!isNullOrUndefined(exportProperties.multipleExport.type) ? exportProperties.multipleExport.type : 'AppendToSheet');
                    if (!isNullOrUndefined(exportProperties.multipleExport.blankRows)) {
                        blankRows = exportProperties.multipleExport.blankRows;
                    }
                }
                if (isNullOrUndefined(workBook)) {
                    this.workSheet = [];
                    this.rows = [];
                    this.columns = [];
                    this.images = [];
                }
                else if (expType === 'NewSheet') {
                    this.rows = [];
                    this.columns = [];
                    this.images = [];
                }
                else {
                    this.workSheet = [];
                    this.rows = workBook['worksheets'][0].rows;
                    this.columns = workBook['worksheets'][0].columns;
                    this.images = workBook['worksheets'][0].images;
                    this.actualrCnt = (this.rows[this.rows.length - 1].index + (blankRows - 1));
                    this.actualrCnt++;
                }
                this.parent = currentPivotInstance ? currentPivotInstance : this.parent;
                const isHeaderDefined = !isNullOrUndefined(exportProperties) && !isNullOrUndefined(exportProperties.header);
                const isFooterDefined = !isNullOrUndefined(exportProperties) && !isNullOrUndefined(exportProperties.footer);
                const isFileNameDefined = !isNullOrUndefined(exportProperties) && !isNullOrUndefined(exportProperties.fileName);
                this.engine = this.parent.dataType === 'olap' ? this.parent.olapEngineModule : this.parent.engineModule;
                this.theme = !isNullOrUndefined(exportProperties) ? exportProperties.theme : undefined;
                /** Event trigerring */
                let clonedValues;
                const currentPivotValues = PivotExportUtil.getClonedPivotValues(this.engine.pivotValues);
                const customFileName = isFileNameDefined ? exportProperties.fileName : type === 'CSV' ? 'default.csv' : 'default.xlsx';
                if (this.parent.exportAllPages && (this.parent.enableVirtualization || this.parent.enablePaging)) {
                    const pageSettings = this.engine.pageSettings;
                    let mdxQuery;
                    this.engine.isPagingOrVirtualizationEnabled = false;
                    this.engine.enableVirtualization = false;
                    this.engine.enablePaging = false;
                    if (this.parent.dataType === 'olap') {
                        this.updateOlapPageSettings(true);
                        mdxQuery = this.parent.olapEngineModule.mdxQuery.slice(0);
                    }
                    else {
                        this.engine.pageSettings = null;
                    }
                    const dataSourceSettings = !isNullOrUndefined(currentPivotInstance) ?
                        currentPivotInstance.dataSourceSettings : this.parent.dataSourceSettings;
                    this.engine.generateGridData(dataSourceSettings, true, true);
                    this.parent.applyFormatting(this.engine.pivotValues, dataSourceSettings);
                    clonedValues = PivotExportUtil.getClonedPivotValues(this.engine.pivotValues);
                    this.engine.pivotValues = currentPivotValues;
                    this.engine.pageSettings = pageSettings;
                    this.engine.isPagingOrVirtualizationEnabled = true;
                    this.engine.enableVirtualization = this.parent.enableVirtualization;
                    this.engine.enablePaging = this.parent.enablePaging;
                    if (this.parent.dataType === 'olap') {
                        this.updateOlapPageSettings(false);
                        this.parent.olapEngineModule.mdxQuery = mdxQuery;
                    }
                }
                else {
                    clonedValues = currentPivotValues;
                }
                const args = {
                    fileName: customFileName, header: '', footer: '', dataCollections: [clonedValues], excelExportProperties: exportProperties
                };
                let fileName;
                let header;
                let footer;
                let dataCollections;
                this.parent.trigger(events.beforeExport, args, (observedArgs) => {
                    fileName = observedArgs.fileName;
                    header = observedArgs.header;
                    footer = observedArgs.footer;
                    dataCollections = observedArgs.dataCollections;
                });
                if ((!this.isHeaderIncluded && expType === 'AppendToSheet') || (expType === 'NewSheet')) {
                    if (!isHeaderDefined && isNullOrUndefined(args.excelExportProperties) && header !== '') {
                        this.addHeaderAndFooter({}, header, 'header', undefined);
                    }
                    else if (!isNullOrUndefined(args.excelExportProperties) && !isNullOrUndefined(args.excelExportProperties.header)) {
                        this.addHeaderAndFooter(args.excelExportProperties.header, '', 'header', args.excelExportProperties.header.headerRows);
                    }
                    this.isHeaderIncluded = true;
                }
                const includeHiddenColumn = args.excelExportProperties && args.excelExportProperties.includeHiddenColumn ?
                    args.excelExportProperties.includeHiddenColumn : true;
                const col = currentPivotInstance ? currentPivotInstance.grid.getColumns() : this.parent.grid.getColumns();
                const hiddenColumnsIndex = [];
                if (!includeHiddenColumn) {
                    for (let column = 0; column < col.length; column++) {
                        if (!col[column].visible) {
                            hiddenColumnsIndex.push(column);
                        }
                    }
                }
                let columnCount = 0;
                let rowHeight = 0;
                for (let dataColl = 0; dataColl < dataCollections.length; dataColl++) {
                    let pivotValues = dataCollections[dataColl];
                    let colLen = 0;
                    const isEmptyPivotTable = PivotUtil.getPivotEmptyInfo(this.parent, this.engine);
                    if (isEmptyPivotTable) {
                        pivotValues = PivotUtil.getEmptyPivotValues(this.parent);
                    }
                    const rowLen = pivotValues.length;
                    const formatList = currentPivotInstance ? currentPivotInstance.renderModule.formatList
                        : this.parent.renderModule.formatList;
                    let maxLevel = 0;
                    for (let colCount = 0; colCount < pivotValues[0].length; colCount++) {
                        if (pivotValues[0][colCount] !== null &&
                            pivotValues[0][colCount] !== undefined) {
                            columnCount++;
                        }
                    }
                    for (let rCnt = 0; rCnt < rowLen; rCnt++) {
                        if (pivotValues[rCnt]) {
                            this.actualrCnt++;
                            if (!includeHiddenColumn) {
                                for (const colIndex of hiddenColumnsIndex) {
                                    pivotValues[rCnt].splice(colIndex, 1);
                                }
                            }
                            colLen = pivotValues[rCnt].length;
                            const cells = [];
                            for (let cCnt = 0; cCnt < colLen; cCnt++) {
                                if (pivotValues[rCnt][cCnt]) {
                                    const pivotCell = pivotValues[rCnt][cCnt];
                                    const field = (this.parent.dataSourceSettings.valueAxis === 'row' &&
                                        this.parent.dataType === 'olap' && pivotCell.rowOrdinal &&
                                        this.engine.tupRowInfo[pivotCell.rowOrdinal]) ?
                                        this.engine.tupRowInfo[pivotCell.rowOrdinal].measureName :
                                        pivotCell.actualText;
                                    const styles = (pivotCell.axis === 'row') ? { hAlign: 'Left', bold: true, wrapText: true } : { numberFormat: formatList[field], bold: false, wrapText: true };
                                    const headerStyle = { bold: true, vAlign: 'Center', wrapText: true, indent: cCnt === 0 ? pivotCell.level * 10 : 0 };
                                    if (!(pivotCell.level === -1 && !pivotCell.rowSpan)) {
                                        const aggMatrix = this.engine.aggregatedValueMatrix;
                                        let cellValue = pivotCell.axis === 'value' ?
                                            ((aggMatrix[rCnt] && aggMatrix[rCnt][cCnt]) ?
                                                aggMatrix[rCnt][cCnt] :
                                                ((pivotCell.formattedText === '#DIV/0!' || isEmptyPivotTable) ? pivotCell.formattedText :
                                                    pivotCell.formattedText === '' ? '' : pivotCell.value)) :
                                            pivotCell.formattedText;
                                        const isgetValuesHeader = ((this.parent.dataSourceSettings.rows.length === 0 && this.parent.dataSourceSettings.valueAxis === 'row')
                                            || (this.parent.dataSourceSettings.columns.length === 0 && this.parent.dataSourceSettings.valueAxis === 'column'));
                                        if (pivotCell.type === 'grand sum' && !(this.parent.dataSourceSettings.values.length === 1 && this.parent.dataSourceSettings.valueAxis === 'row' && pivotCell.axis === 'column')) {
                                            cellValue = isgetValuesHeader ? this.parent.getValuesHeader(pivotCell, 'grandTotal') : this.parent.localeObj.getConstant('grandTotal');
                                        }
                                        else if (pivotCell.type === 'sum') {
                                            cellValue = cellValue.toString().replace('Total', this.parent.localeObj.getConstant('total'));
                                        }
                                        else {
                                            cellValue = (!isNullOrUndefined(pivotCell.valueSort) && (this.parent.localeObj.getConstant('grandTotal') + this.parent.dataSourceSettings.valueSortSettings.headerDelimiter + pivotCell.formattedText
                                                === pivotCell.valueSort.levelName) && isgetValuesHeader) ? this.parent.getValuesHeader(pivotCell, 'value') : cellValue;
                                        }
                                        pivotCell.formattedText =
                                            !isNullOrUndefined(cellValue) ? cellValue.toString() : cellValue;
                                        const isHeaderCollapsed = pivotCell.hasChild === true && pivotCell.isDrilled === false;
                                        const isSubTotalCell = pivotCell.type === 'sum' || pivotCell.type === 'grand sum';
                                        const isRepeatLabelEnabled = this.parent.gridSettings.repeatItemLabels && !isHeaderCollapsed && !isSubTotalCell;
                                        if (!(pivotCell.level === -1 && !pivotCell.rowSpan)) {
                                            const forcedRowSpan = !isRepeatLabelEnabled ? pivotCell.rowSpan
                                                : ((pivotCell.rowSpan === 0 || pivotCell.rowSpan > 1) ? 1 :
                                                    (pivotCell.rowSpan === -1 ? 1 : pivotCell.rowSpan));
                                            if (forcedRowSpan !== 0) {
                                                cells.push({
                                                    index: cCnt + 1, value: cellValue,
                                                    colSpan: pivotCell.colSpan, rowSpan: forcedRowSpan
                                                });
                                                const lastCell = cells[cells.length - 1];
                                                if (pivotCell.axis === 'value') {
                                                    if (isNaN(pivotCell.value) || pivotCell.formattedText === '' ||
                                                        pivotCell.formattedText === undefined || isNullOrUndefined(pivotCell.value)) {
                                                        lastCell.value = type === 'Excel' ? null : '';
                                                    }
                                                    styles.numberFormat = typeof cellValue === 'string' ? undefined : styles.numberFormat;
                                                    lastCell.style = styles;
                                                }
                                                else {
                                                    lastCell.style = headerStyle;
                                                    if (pivotCell.axis === 'row' &&
                                                        (this.parent.isTabular ? cCnt < this.parent.engineModule.rowMaxLevel + 1 :
                                                            cCnt === 0)) {
                                                        lastCell.style = styles;
                                                        if (this.parent.dataType === 'olap') {
                                                            const indent = this.parent.renderModule.indentCollection[rCnt];
                                                            lastCell.style.indent = indent * 2;
                                                            maxLevel = maxLevel > indent ? maxLevel : indent;
                                                        }
                                                        else {
                                                            const levelName = pivotCell.valueSort ? pivotCell.valueSort.levelName.toString() : '';
                                                            const delimiter = this.parent.dataSourceSettings.valueSortSettings.headerDelimiter;
                                                            const memberPos = pivotCell.actualText ?
                                                                pivotCell.actualText.toString().split(delimiter).length : 0;
                                                            const levelPosition = levelName.split(delimiter).length -
                                                                (memberPos ? memberPos - 1 : memberPos);
                                                            const level = levelPosition ? (levelPosition - 1) : 0;
                                                            lastCell.style.indent = !this.parent.isTabular ? level * 2 : 0;
                                                            maxLevel = level > maxLevel ? level : maxLevel;
                                                        }
                                                    }
                                                }
                                                if (pivotCell.style || lastCell.style.backColor || lastCell.style.fontColor ||
                                                    lastCell.style.fontName || lastCell.style.fontSize) {
                                                    lastCell.style.backColor = lastCell.style.backColor ? lastCell.style.backColor
                                                        : pivotCell.style.backgroundColor;
                                                    lastCell.style.fontColor = lastCell.style.fontColor ? lastCell.style.fontColor
                                                        : pivotCell.style.color;
                                                    lastCell.style.fontName = lastCell.style.fontName ? lastCell.style.fontName
                                                        : pivotCell.style.fontFamily;
                                                    if (!isNullOrUndefined(lastCell.style.fontSize) ||
                                                        !isNullOrUndefined(pivotCell.style.fontSize)) {
                                                        lastCell.style.fontSize = !isNullOrUndefined(lastCell.style.fontSize) ?
                                                            Number(lastCell.style.fontSize) : Number(pivotCell.style.fontSize.split('px')[0]);
                                                    }
                                                }
                                                lastCell.style.borders = { color: '#000000', lineStyle: 'thin' };
                                                let excelHeaderQueryCellInfoArgs;
                                                let excelQueryCellInfoArgs;
                                                if (pivotCell.axis === 'column') {
                                                    excelHeaderQueryCellInfoArgs = {
                                                        style: !isNullOrUndefined(this.theme) && !isNullOrUndefined(this.theme.header) ?
                                                            this.excelExportHelper.getHeaderThemeStyle(this.theme, headerStyle)
                                                            : headerStyle,
                                                        cell: pivotCell
                                                    };
                                                    this.parent.trigger(events.excelHeaderQueryCellInfo, excelHeaderQueryCellInfoArgs);
                                                }
                                                else {
                                                    excelQueryCellInfoArgs = {
                                                        style: !isNullOrUndefined(this.theme) && !isNullOrUndefined(this.theme.record) ?
                                                            this.excelExportHelper.getRecordThemeStyle(this.theme, styles)
                                                            : styles,
                                                        cell: pivotCell,
                                                        column: undefined,
                                                        data: pivotValues,
                                                        value: cellValue,
                                                        colSpan: 1
                                                    };
                                                    this.parent.trigger(events.excelQueryCellInfo, excelQueryCellInfoArgs);
                                                }
                                                lastCell.value = (pivotCell.axis === 'column') ?
                                                    excelHeaderQueryCellInfoArgs.cell.formattedText :
                                                    excelQueryCellInfoArgs.value;
                                                lastCell.style = (pivotCell.axis === 'column') ? excelHeaderQueryCellInfoArgs.style
                                                    : excelQueryCellInfoArgs.style;
                                                if ((excelHeaderQueryCellInfoArgs && excelHeaderQueryCellInfoArgs.image) ||
                                                    (excelQueryCellInfoArgs && excelQueryCellInfoArgs.image)) {
                                                    rowHeight = this.excelExportHelper.setImage((pivotCell.axis === 'column') ?
                                                        excelHeaderQueryCellInfoArgs : excelQueryCellInfoArgs, cCnt, this.actualrCnt, rowHeight);
                                                }
                                                if (!isNullOrUndefined(excelHeaderQueryCellInfoArgs) &&
                                                    !isNullOrUndefined(excelHeaderQueryCellInfoArgs.hyperLink)) {
                                                    lastCell.hyperlink = { target: excelHeaderQueryCellInfoArgs.hyperLink.target };
                                                    lastCell.value = excelHeaderQueryCellInfoArgs.hyperLink.displayText || lastCell.value;
                                                }
                                                else if (!isNullOrUndefined(excelQueryCellInfoArgs) &&
                                                    !isNullOrUndefined(excelQueryCellInfoArgs.hyperLink)) {
                                                    lastCell.hyperlink = { target: excelQueryCellInfoArgs.hyperLink.target };
                                                    lastCell.value = excelQueryCellInfoArgs.hyperLink.displayText || lastCell.value;
                                                }
                                                if (pivotCell.axis === 'column') {
                                                    lastCell.colSpan = excelHeaderQueryCellInfoArgs.cell.colSpan;
                                                    lastCell.rowSpan = excelHeaderQueryCellInfoArgs.cell.rowSpan;
                                                }
                                                else {
                                                    lastCell.colSpan = excelQueryCellInfoArgs.colSpan > 1 ? excelQueryCellInfoArgs.colSpan :
                                                        excelQueryCellInfoArgs.cell.colSpan;
                                                    lastCell.rowSpan = excelQueryCellInfoArgs.cell.rowSpan;
                                                }
                                                if (isRepeatLabelEnabled) {
                                                    lastCell.rowSpan = 1;
                                                }
                                            }
                                        }
                                    }
                                    cCnt = cCnt + (pivotCell.colSpan ? (pivotCell.colSpan - 1) : 0);
                                }
                                else {
                                    const pivotCell = { formattedText: '', colSpan: 1, rowSpan: 1 };
                                    if (rCnt === 0 && cCnt === 0 && !isEmptyPivotTable) {
                                        if (!includeHiddenColumn) {
                                            pivotCell.colSpan = pivotValues[0].length - (columnCount - hiddenColumnsIndex.length);
                                            pivotCell.rowSpan = Object.keys(pivotValues).length - this.engine.rowCount;
                                        }
                                        else {
                                            pivotCell.colSpan = this.parent.isTabular ? (this.parent.engineModule.rowMaxLevel + 1) : 1;
                                            pivotCell.rowSpan = Object.keys(this.engine.headerContent).length;
                                        }
                                    }
                                    let excelHeaderQueryCellInfoArgs;
                                    if (pivotCell) {
                                        excelHeaderQueryCellInfoArgs = {
                                            style: { borders: { color: '#000000', lineStyle: 'thin' } },
                                            cell: pivotCell
                                        };
                                        this.parent.trigger(events.excelHeaderQueryCellInfo, excelHeaderQueryCellInfoArgs);
                                    }
                                    const cell = excelHeaderQueryCellInfoArgs.cell;
                                    cells.push({
                                        index: cCnt + 1, colSpan: cell['colSpan'], rowSpan: cell['rowSpan'],
                                        value: pivotCell.formattedText, style: excelHeaderQueryCellInfoArgs.style
                                    });
                                    if (excelHeaderQueryCellInfoArgs.image) {
                                        rowHeight =
                                            this.excelExportHelper.setImage(excelHeaderQueryCellInfoArgs, cCnt, this.actualrCnt, rowHeight);
                                    }
                                    if (!isNullOrUndefined(excelHeaderQueryCellInfoArgs) &&
                                        !isNullOrUndefined(excelHeaderQueryCellInfoArgs.hyperLink)) {
                                        cell.hyperlink = { target: excelHeaderQueryCellInfoArgs.hyperLink.target };
                                        cell.value = excelHeaderQueryCellInfoArgs.hyperLink.displayText || cell.value;
                                    }
                                }
                            }
                            const row = { index: this.actualrCnt, cells: cells };
                            if (rowHeight > 0) {
                                row.height = rowHeight;
                                rowHeight = 0;
                            }
                            this.rows.push(row);
                        }
                    }
                    if ((!isMultipleExport && expType === 'AppendToSheet') || expType === 'NewSheet') {
                        if (isFooterDefined) {
                            this.addHeaderAndFooter(exportProperties.footer, '', 'footer', exportProperties.footer.footerRows);
                        }
                        else if (!isFooterDefined && footer !== '' && isNullOrUndefined(args.excelExportProperties)) {
                            this.addHeaderAndFooter({}, footer, 'footer', undefined);
                        }
                        else if (!isNullOrUndefined(args.excelExportProperties) && !isNullOrUndefined(args.excelExportProperties.footer)) {
                            this.addHeaderAndFooter(args.excelExportProperties.footer, '', 'footer', args.excelExportProperties.footer.footerRows);
                        }
                    }
                    if (this.parent.enableVirtualization) {
                        this.columns = [];
                        for (let cCnt = 0; cCnt < colLen; cCnt++) {
                            this.columns.push({ index: cCnt + 1, width: this.parent.gridSettings.columnWidth });
                        }
                    }
                    else {
                        if (this.columns.length < col.length) {
                            this.columns = [];
                            for (let cCnt = 0; cCnt < colLen; cCnt++) {
                                let width = !isNullOrUndefined(col[cCnt]) ? col[cCnt].width :
                                    this.parent.gridSettings.columnWidth;
                                if (typeof (width) === 'string' && width.indexOf('px') !== -1) {
                                    width = parseInt(width, 10);
                                }
                                this.columns.push({ index: cCnt + 1, width: width });
                            }
                        }
                    }
                    if (maxLevel > 0) {
                        this.columns[0].width = 100 + (maxLevel * 20);
                    }
                    const sheet = { columns: this.columns, rows: this.rows, images: this.images,
                        enableRtl: this.parent.enableRtl };
                    this.workSheet.push(sheet);
                    this.book['worksheets'] = this.workSheet;
                }
                let blobData;
                if (!isMultipleExport) {
                    const book = new Workbook(this.book, type === 'Excel' ? 'xlsx' : 'csv', undefined, this.parent.currencyCode);
                    const fileExtension = fileName.split('.').pop();
                    if (!isBlob) {
                        book.save(fileExtension === 'xlsx' || fileExtension === 'csv' ? fileName : (fileName + (type === 'Excel' ? '.xlsx' : '.csv')));
                    }
                    else {
                        blobData = book.saveAsBlob(fileExtension === 'xlsx' || type === 'Excel' ?
                            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' : 'text/csv');
                    }
                    const exportCompleteEventArgs = {
                        type: type,
                        promise: isBlob ? blobData : null
                    };
                    this.parent.trigger(events.exportComplete, exportCompleteEventArgs);
                    this.isHeaderIncluded = false;
                }
                resolve(this.book);
            }
            catch (error) {
                reject(error);
            }
        });
    }
    updateOlapPageSettings(isUpdate) {
        this.parent.olapEngineModule.isExporting = isUpdate ? true : false;
        if (!this.parent.exportSpecifiedPages) {
            this.parent.olapEngineModule.pageSettings = isUpdate ? null : this.parent.olapEngineModule.pageSettings;
            this.parent.olapEngineModule.isPaging = isUpdate ? false : true;
        }
        else {
            this.parent.olapEngineModule.exportSpeciedPages = this.parent.exportSpecifiedPages = isUpdate ?
                this.parent.exportSpecifiedPages : undefined;
        }
    }
    /**
     * To destroy the excel export module
     *
     * @returns {void}
     * @hidden
     */
    destroy() {
        this.rows = [];
        this.actualrCnt = 0;
        if (this.engine) {
            this.engine = null;
        }
        if (this.rows) {
            this.rows = null;
        }
    }
}
